-- =============================================================================
-- Hasad ERP - Complete PostgreSQL Schema & Initial Data for Supabase
-- نظام حصاد (Hasad ERP) - المخطط الشامل لقاعدة بيانات PostgreSQL المتوافقة مع Supabase
-- =============================================================================

-- تفعيل الإضافات الأساسية
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- -----------------------------------------------------------------------------
-- 1. جدول تتبع تهجيرات لارافيل (migrations)
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS migrations (
    id SERIAL PRIMARY KEY,
    migration VARCHAR(255) NOT NULL,
    batch INTEGER NOT NULL
);

-- -----------------------------------------------------------------------------
-- 2. جداول المستخدمين والمصادقة والجلسات
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS users (
    id BIGSERIAL PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    email VARCHAR(255) UNIQUE NOT NULL,
    phone VARCHAR(255),
    role VARCHAR(255) DEFAULT 'admin',
    is_active BOOLEAN DEFAULT TRUE,
    email_verified_at TIMESTAMP NULL,
    password VARCHAR(255) NOT NULL,
    remember_token VARCHAR(100),
    created_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS password_reset_tokens (
    email VARCHAR(255) PRIMARY KEY,
    token VARCHAR(255) NOT NULL,
    created_at TIMESTAMP NULL
);

CREATE TABLE IF NOT EXISTS sessions (
    id VARCHAR(255) PRIMARY KEY,
    user_id BIGINT NULL,
    ip_address VARCHAR(45) NULL,
    user_agent TEXT NULL,
    payload TEXT NOT NULL,
    last_activity INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_sessions_user_id ON sessions(user_id);
CREATE INDEX IF NOT EXISTS idx_sessions_last_activity ON sessions(last_activity);

-- -----------------------------------------------------------------------------
-- 3. جداول التخزين المؤقت والمهام (Cache & Jobs)
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS cache (
    key VARCHAR(255) PRIMARY KEY,
    value TEXT NOT NULL,
    expiration BIGINT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_cache_expiration ON cache(expiration);

CREATE TABLE IF NOT EXISTS cache_locks (
    key VARCHAR(255) PRIMARY KEY,
    owner VARCHAR(255) NOT NULL,
    expiration BIGINT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_cache_locks_expiration ON cache_locks(expiration);

CREATE TABLE IF NOT EXISTS jobs (
    id BIGSERIAL PRIMARY KEY,
    queue VARCHAR(255) NOT NULL,
    payload TEXT NOT NULL,
    attempts SMALLINT NOT NULL,
    reserved_at INTEGER NULL,
    available_at INTEGER NOT NULL,
    created_at INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_jobs_queue ON jobs(queue);

CREATE TABLE IF NOT EXISTS job_batches (
    id VARCHAR(255) PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    total_jobs INTEGER NOT NULL,
    pending_jobs INTEGER NOT NULL,
    failed_jobs INTEGER NOT NULL,
    failed_job_ids TEXT NOT NULL,
    options TEXT NULL,
    cancelled_at INTEGER NULL,
    created_at INTEGER NOT NULL,
    finished_at INTEGER NULL
);

CREATE TABLE IF NOT EXISTS failed_jobs (
    id BIGSERIAL PRIMARY KEY,
    uuid VARCHAR(255) UNIQUE NOT NULL,
    connection TEXT NOT NULL,
    queue TEXT NOT NULL,
    payload TEXT NOT NULL,
    exception TEXT NOT NULL,
    failed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- -----------------------------------------------------------------------------
-- 4. التقسيم الإداري والجغرافي الرباعي لليمن
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS governorates (
    id BIGINT PRIMARY KEY,
    code VARCHAR(50) UNIQUE NOT NULL,
    name_ar VARCHAR(255) NOT NULL,
    name VARCHAR(255) NULL,
    is_active BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS directorates (
    id BIGINT PRIMARY KEY,
    governorate_id BIGINT NOT NULL REFERENCES governorates(id) ON DELETE CASCADE,
    code VARCHAR(50) UNIQUE NOT NULL,
    name_ar VARCHAR(255) NOT NULL,
    name VARCHAR(255) NULL,
    is_active BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_directorates_gov_id ON directorates(governorate_id);

CREATE TABLE IF NOT EXISTS uzlahs (
    id BIGINT PRIMARY KEY,
    directorate_id BIGINT NOT NULL REFERENCES directorates(id) ON DELETE CASCADE,
    governorate_id BIGINT NOT NULL REFERENCES governorates(id) ON DELETE CASCADE,
    code VARCHAR(50) UNIQUE NOT NULL,
    name_ar VARCHAR(255) NOT NULL,
    name VARCHAR(255) NULL,
    type VARCHAR(50) DEFAULT 'عزلة',
    is_active BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_uzlahs_dir_id ON uzlahs(directorate_id);
CREATE INDEX IF NOT EXISTS idx_uzlahs_gov_id ON uzlahs(governorate_id);

CREATE TABLE IF NOT EXISTS villages (
    id BIGSERIAL PRIMARY KEY,
    uzlah_id BIGINT NULL REFERENCES uzlahs(id) ON DELETE CASCADE,
    sub_district_id BIGINT NULL,
    name VARCHAR(255) NOT NULL,
    is_active BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP
);

-- إنشاء الـ Views للتوافق المزدوج
CREATE OR REPLACE VIEW districts AS
SELECT id, governorate_id, code, name_ar, COALESCE(name, name_ar) AS name, is_active, created_at, updated_at
FROM directorates;

CREATE OR REPLACE VIEW sub_districts AS
SELECT id, directorate_id AS district_id, governorate_id, code, name_ar, COALESCE(name, name_ar) AS name, type, is_active, created_at, updated_at
FROM uzlahs;

-- -----------------------------------------------------------------------------
-- 5. المستوى الرابع الديناميكي (القرى / المحلات / الجمعيات / المناطق الفرعية)
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS sub_locations (
    id BIGSERIAL PRIMARY KEY,
    uzlah_id BIGINT NOT NULL REFERENCES uzlahs(id) ON DELETE CASCADE,
    directorate_id BIGINT NOT NULL REFERENCES directorates(id) ON DELETE CASCADE,
    governorate_id BIGINT NOT NULL REFERENCES governorates(id) ON DELETE CASCADE,
    code VARCHAR(50) UNIQUE NOT NULL,
    name_ar VARCHAR(255) NOT NULL,
    entity_type VARCHAR(50) DEFAULT 'قرية',
    notes TEXT NULL,
    is_active INTEGER DEFAULT 1,
    created_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT sub_locations_uzlah_name_type_unique UNIQUE (uzlah_id, name_ar, entity_type)
);
CREATE INDEX IF NOT EXISTS idx_sub_locations_uzlah_id ON sub_locations(uzlah_id);
CREATE INDEX IF NOT EXISTS idx_sub_locations_directorate_id ON sub_locations(directorate_id);
CREATE INDEX IF NOT EXISTS idx_sub_locations_governorate_id ON sub_locations(governorate_id);
CREATE INDEX IF NOT EXISTS idx_sub_locations_name_ar ON sub_locations(name_ar);
CREATE INDEX IF NOT EXISTS idx_sub_locations_entity_type ON sub_locations(entity_type);

-- -----------------------------------------------------------------------------
-- 6. الجمعيات التعاونية وأعضاء الهيئة الإدارية (Associations & Board Members)
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS associations (
    id BIGSERIAL PRIMARY KEY,
    code VARCHAR(50) UNIQUE NOT NULL,
    name VARCHAR(255) NOT NULL,
    type VARCHAR(100) DEFAULT 'زراعية',
    license_number VARCHAR(100) NULL,
    license_date DATE NULL,
    founded_date DATE NULL,
    announced_date DATE NULL,
    status VARCHAR(50) DEFAULT 'نشطة',
    governorate_id BIGINT NOT NULL REFERENCES governorates(id) ON DELETE CASCADE,
    directorate_id BIGINT NOT NULL REFERENCES directorates(id) ON DELETE CASCADE,
    uzlah_id BIGINT NOT NULL REFERENCES uzlahs(id) ON DELETE CASCADE,
    sub_location_id BIGINT NULL REFERENCES sub_locations(id) ON DELETE SET NULL,
    address VARCHAR(255) NULL,
    phone VARCHAR(50) NULL,
    email VARCHAR(100) NULL,
    website_url VARCHAR(255) NULL,
    issuing_authority VARCHAR(255) NULL,
    license_status VARCHAR(100) NULL,
    has_bylaws BOOLEAN DEFAULT TRUE,
    has_member_registry BOOLEAN DEFAULT TRUE,
    has_founding_minutes BOOLEAN DEFAULT TRUE,
    has_headquarters BOOLEAN DEFAULT TRUE,
    headquarters_ownership VARCHAR(50) DEFAULT 'إيجار',
    holds_regular_meetings BOOLEAN DEFAULT TRUE,
    last_general_assembly_date DATE NULL,
    last_election_date DATE NULL,
    last_data_update_date DATE NULL,
    president_name VARCHAR(150) NULL,
    president_phone VARCHAR(50) NULL,
    vice_president_name VARCHAR(150) NULL,
    secretary_general_name VARCHAR(150) NULL,
    financial_officer_name VARCHAR(150) NULL,
    oversight_officer_name VARCHAR(150) NULL,
    executive_director_name VARCHAR(150) NULL,
    board_members_count INTEGER DEFAULT 7,
    oversight_members_count INTEGER DEFAULT 3,
    board_status VARCHAR(50) DEFAULT 'سارية',
    board_term_end_date DATE NULL,
    employees_count INTEGER DEFAULT 0,
    volunteers_count INTEGER DEFAULT 0,
    total_members INTEGER DEFAULT 0,
    male_members INTEGER DEFAULT 0,
    female_members INTEGER DEFAULT 0,
    new_members_this_year INTEGER DEFAULT 0,
    beneficiaries_count INTEGER DEFAULT 0,
    beneficiary_families_count INTEGER DEFAULT 0,
    initial_capital NUMERIC(15, 2) DEFAULT 0,
    current_capital NUMERIC(15, 2) DEFAULT 0,
    share_value NUMERIC(10, 2) DEFAULT 1000,
    shares_count INTEGER DEFAULT 0,
    annual_subscription_fee NUMERIC(10, 2) DEFAULT 0,
    total_assets_value NUMERIC(15, 2) DEFAULT 0,
    has_bank_account BOOLEAN DEFAULT FALSE,
    has_accounting_records BOOLEAN DEFAULT TRUE,
    last_approved_budget_date DATE NULL,
    main_activities TEXT NULL,
    agricultural_activities TEXT NULL,
    marketing_activities TEXT NULL,
    productive_activities TEXT NULL,
    service_activities TEXT NULL,
    implemented_projects_count INTEGER DEFAULT 0,
    ongoing_projects_count INTEGER DEFAULT 0,
    stalled_projects_count INTEGER DEFAULT 0,
    planned_projects_count INTEGER DEFAULT 0,
    key_achievements TEXT NULL,
    key_products TEXT NULL,
    annual_production_volume VARCHAR(150) NULL,
    target_markets TEXT NULL,
    partners_and_supporters TEXT NULL,
    agricultural_lands TEXT NULL,
    wells_water_structures TEXT NULL,
    machinery_equipment TEXT NULL,
    transport_vehicles TEXT NULL,
    warehouses TEXT NULL,
    collection_marketing_centers TEXT NULL,
    buildings_headquarters TEXT NULL,
    other_assets TEXT NULL,
    estimated_assets_value NUMERIC(15, 2) DEFAULT 0,
    cooperative_activity_level VARCHAR(50) DEFAULT 'متوسط',
    administrative_status VARCHAR(50) DEFAULT 'مستقر',
    financial_status VARCHAR(50) DEFAULT 'مستقر',
    legal_status VARCHAR(50) DEFAULT 'ساري',
    activity_execution_level VARCHAR(50) DEFAULT 'جيد',
    top_needs TEXT NULL,
    challenges_difficulties TEXT NULL,
    training_needs TEXT NULL,
    required_support TEXT NULL,
    last_field_visit_date DATE NULL,
    visiting_entity VARCHAR(150) NULL,
    monitoring_team_notes TEXT NULL,
    recommendations TEXT NULL,
    general_evaluation VARCHAR(50) DEFAULT 'جيد',
    created_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_associations_geo ON associations(governorate_id, directorate_id, uzlah_id);
CREATE INDEX IF NOT EXISTS idx_associations_name ON associations(name);
CREATE INDEX IF NOT EXISTS idx_associations_status ON associations(status);
CREATE INDEX IF NOT EXISTS idx_associations_type ON associations(type);

CREATE TABLE IF NOT EXISTS association_board_members (
    id BIGSERIAL PRIMARY KEY,
    association_id BIGINT NOT NULL REFERENCES associations(id) ON DELETE CASCADE,
    full_name VARCHAR(255) NOT NULL,
    gender VARCHAR(20) DEFAULT 'ذكر',
    birth_date DATE NULL,
    national_id VARCHAR(50) NULL,
    education_level VARCHAR(100) NULL,
    specialization VARCHAR(100) NULL,
    governorate_id BIGINT NULL REFERENCES governorates(id) ON DELETE SET NULL,
    directorate_id BIGINT NULL REFERENCES directorates(id) ON DELETE SET NULL,
    uzlah_id BIGINT NULL REFERENCES uzlahs(id) ON DELETE SET NULL,
    sub_location_id BIGINT NULL REFERENCES sub_locations(id) ON DELETE SET NULL,
    village_name VARCHAR(150) NULL,
    phone VARCHAR(50) NULL,
    alt_phone VARCHAR(50) NULL,
    role_title VARCHAR(100) DEFAULT 'عضو هيئة إدارية',
    assignment_start_date DATE NULL,
    assignment_end_date DATE NULL,
    membership_status VARCHAR(50) DEFAULT 'نشط',
    assigning_entity VARCHAR(150) NULL,
    notes TEXT NULL,
    created_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_board_members_assoc ON association_board_members(association_id);
CREATE INDEX IF NOT EXISTS idx_board_members_name ON association_board_members(full_name);

-- -----------------------------------------------------------------------------
-- 7. الميسرون والمجاميع الإنتاجية (Facilitators & Productive Groups)
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS facilitators (
    id BIGSERIAL PRIMARY KEY,
    code VARCHAR(50) UNIQUE NOT NULL,
    full_name VARCHAR(255) NOT NULL,
    phone VARCHAR(50) NULL,
    gender VARCHAR(20) DEFAULT 'ذكر',
    education_level VARCHAR(100) NULL,
    specialization VARCHAR(100) NULL,
    experience_field VARCHAR(150) NULL,
    assignment_date DATE NULL,
    assigning_entity VARCHAR(150) NULL,
    assignment_type VARCHAR(50) DEFAULT 'متطوع',
    status VARCHAR(50) DEFAULT 'نشط',
    governorate_id BIGINT NULL REFERENCES governorates(id) ON DELETE SET NULL,
    directorate_id BIGINT NULL REFERENCES directorates(id) ON DELETE SET NULL,
    uzlah_id BIGINT NULL REFERENCES uzlahs(id) ON DELETE SET NULL,
    notes TEXT NULL,
    created_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_facilitators_name ON facilitators(full_name);
CREATE INDEX IF NOT EXISTS idx_facilitators_status ON facilitators(status);

CREATE TABLE IF NOT EXISTS productive_groups (
    id BIGSERIAL PRIMARY KEY,
    code VARCHAR(50) UNIQUE NOT NULL,
    association_id BIGINT NULL REFERENCES associations(id) ON DELETE SET NULL,
    name VARCHAR(255) NOT NULL,
    group_type VARCHAR(100) DEFAULT 'زراعية',
    activity_field VARCHAR(150) NULL,
    productive_activity VARCHAR(150) NULL,
    main_product VARCHAR(150) NULL,
    founded_date DATE NULL,
    founding_minutes_number VARCHAR(100) NULL,
    status VARCHAR(50) DEFAULT 'نشطة',
    governorate_id BIGINT NOT NULL REFERENCES governorates(id) ON DELETE CASCADE,
    directorate_id BIGINT NOT NULL REFERENCES directorates(id) ON DELETE CASCADE,
    uzlah_id BIGINT NOT NULL REFERENCES uzlahs(id) ON DELETE CASCADE,
    sub_location_id BIGINT NULL REFERENCES sub_locations(id) ON DELETE SET NULL,
    leader_name VARCHAR(150) NULL,
    leader_phone VARCHAR(50) NULL,
    total_members INTEGER DEFAULT 0,
    male_members INTEGER DEFAULT 0,
    female_members INTEGER DEFAULT 0,
    youth_members INTEGER DEFAULT 0,
    active_members INTEGER DEFAULT 0,
    main_activity VARCHAR(150) NULL,
    sub_activity VARCHAR(150) NULL,
    productive_area NUMERIC(12, 2) DEFAULT 0,
    area_unit VARCHAR(50) DEFAULT 'هكتار',
    production_volume NUMERIC(12, 2) DEFAULT 0,
    measurement_unit VARCHAR(50) DEFAULT 'كجم',
    production_season VARCHAR(100) NULL,
    production_value NUMERIC(15, 2) DEFAULT 0,
    sales_value NUMERIC(15, 2) DEFAULT 0,
    marketing_method VARCHAR(50) DEFAULT 'عبر الجمعية',
    marketing_destination VARCHAR(150) NULL,
    field_visits_count INTEGER DEFAULT 0,
    last_visit_date DATE NULL,
    meetings_count INTEGER DEFAULT 0,
    trainings_count INTEGER DEFAULT 0,
    implemented_activities TEXT NULL,
    members_interaction_level VARCHAR(50) DEFAULT 'جيد',
    performance_level VARCHAR(50) DEFAULT 'جيد',
    key_achievements TEXT NULL,
    needs TEXT NULL,
    challenges TEXT NULL,
    suggested_actions TEXT NULL,
    last_update_date DATE NULL,
    created_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_prod_groups_geo ON productive_groups(governorate_id, directorate_id, uzlah_id);
CREATE INDEX IF NOT EXISTS idx_prod_groups_assoc ON productive_groups(association_id);
CREATE INDEX IF NOT EXISTS idx_prod_groups_name ON productive_groups(name);
CREATE INDEX IF NOT EXISTS idx_prod_groups_status ON productive_groups(status);

CREATE TABLE IF NOT EXISTS group_facilitators (
    id BIGSERIAL PRIMARY KEY,
    productive_group_id BIGINT NOT NULL REFERENCES productive_groups(id) ON DELETE CASCADE,
    facilitator_id BIGINT NOT NULL REFERENCES facilitators(id) ON DELETE CASCADE,
    assigned_at DATE NULL,
    is_primary BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT group_facilitators_unique UNIQUE (productive_group_id, facilitator_id)
);

-- -----------------------------------------------------------------------------
-- 8. الكوادر وفرسان التنمية والتدريب الموحد (Unified Personnel)
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS unified_personnel (
    id BIGSERIAL PRIMARY KEY,
    code VARCHAR(50) UNIQUE NOT NULL,
    category VARCHAR(100) NOT NULL,
    sub_specialty VARCHAR(100) NULL,
    association_id BIGINT NULL REFERENCES associations(id) ON DELETE SET NULL,
    governorate_id BIGINT NOT NULL REFERENCES governorates(id) ON DELETE CASCADE,
    directorate_id BIGINT NOT NULL REFERENCES directorates(id) ON DELETE CASCADE,
    uzlah_id BIGINT NOT NULL REFERENCES uzlahs(id) ON DELETE CASCADE,
    sub_location_id BIGINT NULL REFERENCES sub_locations(id) ON DELETE SET NULL,
    village_name VARCHAR(150) NULL,
    full_name VARCHAR(255) NOT NULL,
    gender VARCHAR(20) DEFAULT 'ذكر',
    birth_date DATE NULL,
    age INTEGER NULL,
    education_level VARCHAR(100) NULL,
    specialization VARCHAR(100) NULL,
    graduation_date DATE NULL,
    employer VARCHAR(150) NULL,
    phone VARCHAR(50) NULL,
    alt_phone VARCHAR(50) NULL,
    training_program_name VARCHAR(200) NULL,
    target_group VARCHAR(100) NULL,
    training_date DATE NULL,
    blood_type VARCHAR(10) NULL,
    is_activated_in_field BOOLEAN DEFAULT FALSE,
    activation_entity VARCHAR(150) NULL,
    notes TEXT NULL,
    general_program VARCHAR(150) NULL,
    initiative_type VARCHAR(150) NULL,
    trainer_name VARCHAR(150) NULL,
    enrollment_year VARCHAR(20) NULL,
    coordinating_entity VARCHAR(150) NULL,
    activation_type VARCHAR(100) NULL,
    created_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_personnel_cat_spec ON unified_personnel(category, sub_specialty);
CREATE INDEX IF NOT EXISTS idx_personnel_assoc ON unified_personnel(association_id);
CREATE INDEX IF NOT EXISTS idx_personnel_geo ON unified_personnel(governorate_id, directorate_id, uzlah_id);
CREATE INDEX IF NOT EXISTS idx_personnel_name ON unified_personnel(full_name);
CREATE INDEX IF NOT EXISTS idx_personnel_activated ON unified_personnel(is_activated_in_field);

-- -----------------------------------------------------------------------------
-- 9. القروض التمويلية البيضاء - تمويل حسن بدون فوائد 0% (Association Loans)
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS association_loans (
    id BIGSERIAL PRIMARY KEY,
    code VARCHAR(50) UNIQUE NOT NULL,
    association_id BIGINT NULL REFERENCES associations(id) ON DELETE SET NULL,
    governorate_id BIGINT NOT NULL REFERENCES governorates(id) ON DELETE CASCADE,
    directorate_id BIGINT NOT NULL REFERENCES directorates(id) ON DELETE CASCADE,
    loan_type VARCHAR(50) DEFAULT 'ممنوح',
    funding_entity VARCHAR(255) NOT NULL,
    beneficiary_name VARCHAR(255) NOT NULL,
    loan_amount NUMERIC(15, 2) NOT NULL,
    currency VARCHAR(50) DEFAULT 'ريال يمني',
    received_date DATE NULL,
    repayment_period_months INTEGER DEFAULT 12,
    grace_period_months INTEGER DEFAULT 3,
    paid_amount NUMERIC(15, 2) DEFAULT 0,
    remaining_balance NUMERIC(15, 2) DEFAULT 0,
    loan_status VARCHAR(50) DEFAULT 'ساري',
    purpose TEXT NULL,
    collaterals TEXT NULL,
    empowerment_program_name VARCHAR(255) NULL,
    activity_field VARCHAR(150) NULL,
    quantity_description VARCHAR(150) NULL,
    beneficiaries_count INTEGER DEFAULT 1,
    execution_entity VARCHAR(150) NULL,
    funding_type VARCHAR(50) DEFAULT 'قرض أبيض',
    execution_status VARCHAR(50) DEFAULT 'قيد التنفيذ',
    completion_rate NUMERIC(5, 2) DEFAULT 0,
    repayment_status VARCHAR(50) DEFAULT 'قيد السداد',
    data_source VARCHAR(150) NULL,
    notes TEXT NULL,
    created_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_loans_assoc ON association_loans(association_id);
CREATE INDEX IF NOT EXISTS idx_loans_geo ON association_loans(governorate_id, directorate_id);
CREATE INDEX IF NOT EXISTS idx_loans_status ON association_loans(loan_status);
CREATE INDEX IF NOT EXISTS idx_loans_beneficiary ON association_loans(beneficiary_name);

-- -----------------------------------------------------------------------------
-- 10. جداول قاعدة البيانات العامة (المحاور: المشاريع، الزراعة، المزارعون، الوقود)
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS association_projects (
    id BIGSERIAL PRIMARY KEY,
    governorate_id BIGINT NOT NULL REFERENCES governorates(id) ON DELETE CASCADE,
    directorate_id BIGINT NOT NULL REFERENCES directorates(id) ON DELETE CASCADE,
    uzlah_id BIGINT NULL REFERENCES uzlahs(id) ON DELETE SET NULL,
    association_id BIGINT NULL REFERENCES associations(id) ON DELETE SET NULL,
    project_name VARCHAR(255) NOT NULL,
    quantity INTEGER DEFAULT 1,
    project_type VARCHAR(100) NULL,
    execution_status VARCHAR(50) DEFAULT 'قيد التنفيذ',
    cost NUMERIC(15, 2) DEFAULT 0,
    notes TEXT NULL,
    created_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_projects_assoc ON association_projects(association_id);
CREATE INDEX IF NOT EXISTS idx_projects_geo ON association_projects(governorate_id, directorate_id);

CREATE TABLE IF NOT EXISTS awareness_sessions (
    id BIGSERIAL PRIMARY KEY,
    governorate_id BIGINT NOT NULL REFERENCES governorates(id) ON DELETE CASCADE,
    directorate_id BIGINT NOT NULL REFERENCES directorates(id) ON DELETE CASCADE,
    uzlah_id BIGINT NULL REFERENCES uzlahs(id) ON DELETE SET NULL,
    association_id BIGINT NULL REFERENCES associations(id) ON DELETE SET NULL,
    awareness_type VARCHAR(50) DEFAULT 'تطوع',
    target_group VARCHAR(150) NULL,
    beneficiaries_count INTEGER DEFAULT 0,
    sessions_count INTEGER DEFAULT 1,
    cost NUMERIC(15, 2) DEFAULT 0,
    funding_source VARCHAR(150) NULL,
    session_date DATE NULL,
    funding_type VARCHAR(50) DEFAULT 'ذاتي',
    notes TEXT NULL,
    created_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_awareness_type ON awareness_sessions(awareness_type);
CREATE INDEX IF NOT EXISTS idx_awareness_geo ON awareness_sessions(governorate_id, directorate_id);

CREATE TABLE IF NOT EXISTS community_initiatives (
    id BIGSERIAL PRIMARY KEY,
    governorate_id BIGINT NOT NULL REFERENCES governorates(id) ON DELETE CASCADE,
    directorate_id BIGINT NOT NULL REFERENCES directorates(id) ON DELETE CASCADE,
    uzlah_id BIGINT NULL REFERENCES uzlahs(id) ON DELETE SET NULL,
    sub_location_id BIGINT NULL REFERENCES sub_locations(id) ON DELETE SET NULL,
    village_name VARCHAR(150) NULL,
    association_id BIGINT NULL REFERENCES associations(id) ON DELETE SET NULL,
    initiative_name VARCHAR(255) NOT NULL,
    initiative_type VARCHAR(100) NULL,
    initiators_count INTEGER DEFAULT 0,
    beneficiaries_count INTEGER DEFAULT 0,
    support_type VARCHAR(150) NULL,
    execution_entity VARCHAR(150) NULL,
    cost NUMERIC(15, 2) DEFAULT 0,
    funding_source VARCHAR(150) NULL,
    session_date DATE NULL,
    notes TEXT NULL,
    created_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_initiatives_geo ON community_initiatives(governorate_id, directorate_id);

CREATE TABLE IF NOT EXISTS studies_and_research (
    id BIGSERIAL PRIMARY KEY,
    governorate_id BIGINT NOT NULL REFERENCES governorates(id) ON DELETE CASCADE,
    directorate_id BIGINT NOT NULL REFERENCES directorates(id) ON DELETE CASCADE,
    study_name VARCHAR(255) NOT NULL,
    study_type VARCHAR(100) NULL,
    study_field VARCHAR(100) NULL,
    target_group VARCHAR(150) NULL,
    beneficiaries_count INTEGER DEFAULT 0,
    execution_entity VARCHAR(150) NULL,
